package main

import (
	"fmt"
	"regexp"
)

func main() {
	cmd := "ssh nuc02 \"cd ~/photo-archive && git commit --no-gpg-sign -m 'Initial commit of annexed photos\n(1,310 files)'\""

	// Test pattern 1: anchored with (?s)
	p1 := "^(?:(?s)ssh\\s+nuc02\\b.*)$"
	r1, err1 := regexp.Compile(p1)
	fmt.Printf("r1 err: %v, match: %v\n", err1, err1 == nil && r1.MatchString(cmd))

	// Test pattern 2: without (?s), using [\s\S]*
	p2 := "^(?:ssh\\s+nuc02\\b[\\s\\S]*)$"
	r2, err2 := regexp.Compile(p2)
	fmt.Printf("r2 err: %v, match: %v\n", err2, err2 == nil && r2.MatchString(cmd))

    // Test pattern 3: ssh nuc02 .*
	p3 := "^(?:ssh\\s+nuc02\\b.*)$"
	r3, err3 := regexp.Compile(p3)
	fmt.Printf("r3 err: %v, match: %v\n", err3, err3 == nil && r3.MatchString(cmd))
}
EOF

