import sys
sys.path.insert(0, 'src')
import tkinter as tk
from sharex_sync import recctl, defaults, paths

captured = {}

def fake_mainloop(self):
    captured['root'] = self
    self.update()
    raise SystemExit(0)

tk.Tk.mainloop = fake_mainloop
try:
    recctl.run_control(paths.discover_personal_path())
except SystemExit:
    pass

root = captured['root']

def safe(s):
    return s.encode('ascii', 'backslashreplace').decode('ascii')

def walk(w, depth=0):
    cls = w.winfo_class()
    if cls in ('Button', 'Label'):
        text = safe(str(w['text']))
        state = w.cget('state') if 'state' in w.keys() else None
        print('  '*depth + f'{cls} text={text!r} state={state}')
    else:
        print('  '*depth + cls)
    for c in w.winfo_children():
        walk(c, depth+1)

walk(root)
root.destroy()
" 2>&1

